def hook(ctx, nb):
    task = ctx.get('task') or {}
    world = ctx.get('world') or {}
    if not isinstance(task, dict):
        task = {}
    if not isinstance(world, dict):
        world = {}
    target = str(task.get('target_type') or ctx.get('task.target_type') or '').lower()
    dest = str(task.get('destination_type') or ctx.get('task.destination_type') or '').lower()
    ttype = str(task.get('task_type') or ctx.get('task.task_type') or '').lower()
    actinfo = ctx.get('action') or {}
    if not isinstance(actinfo, dict):
        actinfo = {}
    action = str(actinfo.get('final_action') or actinfo.get('normalized') or actinfo.get('raw') or ctx.get('action.final_action') or ctx.get('action.normalized') or ctx.get('action.raw') or '').lower()
    obs = str(ctx.get('observation') or '').lower()
    inv = world.get('inventory') or []
    if isinstance(inv, str):
        inv = [inv.lower()]
    inv_text = ' '.join(str(x).lower() for x in inv)
    has_target = bool(target and target in inv_text and 'nothing' not in inv_text)
    carrying = bool(inv_text and 'nothing' not in inv_text and 'not carrying' not in inv_text)
    if target and target in action and 'nothing' not in action:
        carrying = True
    if target and action.startswith('take ') and target in action and 'nothing' not in action:
        carrying = True
    if target and action.startswith('put ') and target in action:
        carrying = False
    need = ''
    if 'clean' in ttype:
        need = 'clean'
    if 'heat' in ttype:
        need = 'heat'
    if 'cool' in ttype:
        need = 'cool'
    transform_done = bool(nb.get('transformed', False))
    if need and target:
        if action.startswith(need + ' ') and target in action:
            transform_done = True
        if need == 'clean' and target in obs and ('wash' in obs or 'rinse' in obs or 'clean' in obs):
            transform_done = True
        if need == 'heat' and target in obs and 'hot' in obs and 'heat' in obs:
            transform_done = True
        if need == 'cool' and target in obs and 'cold' in obs and 'cool' in obs:
            transform_done = True
    nb['carrying_target'] = carrying
    nb['transformed'] = transform_done
    pc = world.get('placed_count')
    if isinstance(pc, int) and pc > nb.get('placed_count', 0):
        nb['placed_count'] = pc
    locs = world.get('placed_locations') or []
    if locs and not nb.get('placed_locations'):
        nb['placed_locations'] = locs
    items = world.get('placed_items') or []
    if items and not nb.get('placed_items'):
        nb['placed_items'] = items
    take_ready = bool(target and any(a.startswith('take ') and target in a for a in (ctx.get('admissible') or [])))
    put_ready = bool(target and dest and any(a.startswith('put ') and target in a and dest in a for a in (ctx.get('admissible') or [])))
    if carrying and target and dest and not transform_done and need:
        nb['stage'] = 'transform'
    elif carrying and target and dest and transform_done:
        nb['stage'] = 'put_target' if put_ready else 'go_destination'
    elif carrying and target and not transform_done and need:
        nb['stage'] = 'transform'
    elif carrying and target and not transform_done:
        nb['stage'] = 'wrong_inventory'
    elif take_ready or world.get('target_found') or world.get('target_location'):
        nb['stage'] = 'take_target' if take_ready else 'find_target'
    elif carrying and target:
        nb['stage'] = 'go_destination'
    else:
        nb['stage'] = 'find_target'
    if carrying and target and need and not transform_done:
        nb['need_transform'] = need
    return None

def hook(ctx, nb):
    task = ctx.get('task') or {}
    if not isinstance(task, dict):
        task = {}
    ttype = str(task.get('task_type') or ctx.get('task.task_type') or '').lower()
    need = nb.get('need_transform') or ''
    if not need and 'clean' in ttype:
        need = 'clean'
    if not need and 'heat' in ttype:
        need = 'heat'
    if not need and 'cool' in ttype:
        need = 'cool'
    stage = nb.get('stage') or 'find_target'
    target = str(task.get('target_type') or ctx.get('task.target_type') or 'target').lower()
    dest = str(task.get('destination_type') or ctx.get('task.destination_type') or 'destination').lower()
    msg = ''
    if need and stage == 'transform' and not nb.get('transformed') and target:
        msg = 'Before placing, use the admissible action to ' + need + ' the ' + target + '. Do not put an untransformed target at the destination.'
    elif stage == 'transform' and need and target and not nb.get('transformed'):
        msg = 'Carry the ' + target + ' to an appliance that can ' + need + ' it before placing it at the ' + dest + '.'
    elif stage == 'put_target' and target and dest:
        msg = 'The ' + target + ' appears ready; put it at the ' + dest + ' now instead of placing it elsewhere.'
    elif stage == 'wrong_inventory' and target:
        msg = 'You are carrying a non-target item; do not place it at the destination. Recover by setting it down if needed, then find a ' + target + '.'
    elif 'two' in ttype and stage in ('find_target', 'take_target') and nb.get('placed_count', 0) > 0 and target:
        msg = 'One ' + target + ' is already placed; leave it there and find or take another ' + target + ' for the same ' + dest + '.'
    elif stage == 'go_destination' and target and dest:
        msg = 'Keep carrying the ' + target + ' and navigate to the ' + dest + ' for the final put.'
    if not msg:
        return None
    key = stage + ':' + msg[:70]
    if nb.get('last_hint') == key:
        return None
    nb['last_hint'] = key
    return {'message': msg}

