        if need == 'clean' and (action.count(' ') >= 4 or dest in action or (ctx.get('predicates') or {}).get('remaining_steps_low')):
            return {'kind': 'block_and_prompt', 'message': 'This target still needs to be cleaned before placing. Choose an admissible clean action for the target instead of putting it down.'}
